    out = [[0] * w for _ in range(h)]
    for i, off in best.items():
        for r,c in shift(pieces[i]["cells"], off):
            r, c = r-minr, c-minc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = pieces[i]["color"]
    for i, off in best.items():
        for r,c in shift(pieces[i]["ports"], off):
            r, c = r-minr, c-minc
            if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
                out[r][c] = 2
    return out
